CREATE POLICY "prescription_approval_doctor_read" ON public.prescription_approval_workflows FOR SELECT USING ( initiated_by = auth.uid() OR EXISTS ( SELECT 1 FROM user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('doctor', 'pharmacist', 'nurse') AND ur.hospital_id = prescription_approval_workflows.hospital_id ) ); CREATE POLICY "prescription_approval_pharmacist_update" ON public.prescription_approval_workflows FOR UPDATE USING ( EXISTS ( SELECT 1 FROM user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'pharmacist' AND ur.hospital_id = prescription_approval_workflows.hospital_id ) ) WITH CHECK ( EXISTS ( SELECT 1 FROM user_roles ur WHERE ur.user_id = auth.uid() AND ur.role = 'pharmacist' AND ur.hospital_id = prescription_approval_workflows.hospital_id ) ); CREATE INDEX IF NOT EXISTS idx_prescription_approval_hospital_status ON public.prescription_approval_workflows (hospital_id, status); CREATE INDEX IF NOT EXISTS idx_prescription_approval_prescription_id ON public.prescription_approval_workflows (prescription_id); CREATE INDEX IF NOT EXISTS idx_prescription_approval_patient_id ON public.prescription_approval_workflows (patient_id); CREATE INDEX IF NOT EXISTS idx_prescription_approval_initiated_by ON public.prescription_approval_workflows (initiated_by); GRANT SELECT, INSERT, UPDATE ON public.prescription_approval_workflows TO authenticated;